"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Search } from "@/components/ui/icons";

// Command Palette: generated by UIX from the design system. Same variants and sizes as the Figma component.

export interface CommandItem {
  id: string;
  label: string;
  icon?: React.ReactNode;
  /** Keys shown at the end, for example ["⌘", "N"]. */
  shortcut?: string[];
  onSelect?: () => void;
}

export interface CommandGroup {
  heading: string;
  items: CommandItem[];
}

const commandPaletteVariants = cva(
  "m-auto mt-[12vh] w-[calc(100%_-_2rem)] max-w-[560px] overflow-hidden p-0 bg-surface text-fg-primary border border-line-default shadow-xl backdrop:bg-base-black/50 rounded-2xl",
);

export interface CommandPaletteProps
  extends Omit<React.DialogHTMLAttributes<HTMLDialogElement>, "title" | "open" | "onClose">,
    VariantProps<typeof commandPaletteVariants> {
  open: boolean;
  onClose: () => void;
  groups: CommandGroup[];
  placeholder?: string;
  /** Shown when nothing matches. */
  emptyText?: string;
  /** Hint bar under the list. */
  showFooter?: boolean;
}

const CommandPalette = React.forwardRef<HTMLDialogElement, CommandPaletteProps>(
  ({ className, open, onClose, groups, placeholder = "Type a command or search…", emptyText = "No results found.", showFooter = true, ...props }, ref) => {
    const inner = React.useRef<HTMLDialogElement>(null);
    React.useImperativeHandle(ref, () => inner.current as HTMLDialogElement);
    React.useEffect(() => {
      const dialog = inner.current;
      if (!dialog) return;
      if (open && !dialog.open) dialog.showModal();
      if (!open && dialog.open) dialog.close();
    }, [open]);
    const titleId = React.useId();
    const [query, setQuery] = React.useState("");
    const [active, setActive] = React.useState(0);
    const shown = groups.map((group) => ({ ...group, items: group.items.filter((item) => item.label.toLowerCase().includes(query.toLowerCase())) })).filter((group) => group.items.length > 0);
    const flat = shown.flatMap((group) => group.items);
    React.useEffect(() => {
      if (open) setQuery("");
    }, [open]);
    const run = (item?: CommandItem) => {
      if (!item) return;
      item.onSelect?.();
      onClose();
    };
    return (
      <dialog data-slot="command-palette" data-kind="overlay"
        ref={inner}
        aria-label="Command palette"
        className={cn(commandPaletteVariants({  }), className)}
        onClose={onClose}
        onClick={(event) => {
          if (event.target === event.currentTarget) onClose();
        }}
        {...props}
      >
        <div className="flex items-center h-[56px] px-4 gap-3 border-b border-line-subtle [&_svg]:size-5 [&_svg]:text-icon-secondary">
          <Search aria-hidden />
          <input
            role="combobox"
            aria-expanded="true"
            aria-controls={titleId}
            aria-activedescendant={flat[active] ? titleId + "-" + active : void 0}
            autoFocus
            value={query}
            placeholder={placeholder}
            onChange={(event) => {
              setQuery(event.target.value);
              setActive(0);
            }}
            onKeyDown={(event) => {
              if (event.key === "ArrowDown") {
                event.preventDefault();
                setActive((active + 1) % Math.max(flat.length, 1));
              } else if (event.key === "ArrowUp") {
                event.preventDefault();
                setActive((active + Math.max(flat.length, 1) - 1) % Math.max(flat.length, 1));
              } else if (event.key === "Enter") {
                event.preventDefault();
                run(flat[active]);
              }
            }}
            className="min-w-0 flex-1 bg-transparent outline-none text-body-large text-fg-primary placeholder:text-fg-tertiary"
          />
          <kbd className="inline-flex items-center justify-center rounded-sm h-5 px-1-5 bg-subtle border border-line-default text-label-small text-fg-secondary">esc</kbd>
        </div>
        {flat.length ? (
          <div id={titleId} role="listbox" className="flex max-h-80 flex-col overflow-y-auto p-2 gap-2">
            {shown.map((group) => (
              <div key={group.heading} role="group" aria-label={group.heading} className="flex flex-col gap-0-5">
                <p aria-hidden className="px-2 py-1-5 text-label-small text-fg-tertiary">{group.heading}</p>
                {group.items.map((item) => {
                  const index = flat.indexOf(item);
                  return (
                    <button
                      key={item.id}
                      id={titleId + "-" + index}
                      type="button"
                      role="option"
                      aria-selected={index === active}
                      data-active={index === active ? "" : void 0}
                      onMouseEnter={() => setActive(index)}
                      onClick={() => run(item)}
                      className="flex w-full cursor-pointer items-center text-left h-10 px-2 gap-3 rounded-md text-body-medium text-fg-primary data-[active]:bg-subtle [&_svg]:size-[18px] [&_svg]:shrink-0 [&_svg]:text-icon-secondary"
                    >
                      {item.icon}
                      <span className="min-w-0 flex-1 truncate">{item.label}</span>
                      {item.shortcut ? <span className="flex items-center gap-1">{item.shortcut.map((cap) => <kbd key={cap} className="inline-flex items-center justify-center rounded-sm h-5 px-1-5 bg-subtle border border-line-default text-label-small text-fg-secondary">{cap}</kbd>)}</span> : null}
                    </button>
                  );
                })}
              </div>
            ))}
          </div>
        ) : (
          <div role="status" className="flex flex-col items-center text-center gap-2 py-12 [&_svg]:size-8">
            <p className="text-title-small text-fg-primary">{emptyText}</p>
            <p className="text-body-small text-fg-tertiary">Try a different search term.</p>
          </div>
        )}
        {showFooter ? (
          <p className="border-t border-line-subtle bg-subtle px-4 py-[10px] text-body-xs text-fg-tertiary">↑↓ to navigate · ↵ to select · esc to close</p>
        ) : null}
      </dialog>
    );
  },
);
CommandPalette.displayName = "CommandPalette";

export { CommandPalette, commandPaletteVariants };
